+#[test]
+fn run_straight_on_is_the_old_program_and_is_undoable() {
+    let (world, mut h) = doc();
+    let paused = post_as(&world, "Fanuc", "cont-paused").expect("posts");
+    choose(&world, &mut h, BetweenSetups::Continue);
+    let on = post_as(&world, "Fanuc", "cont-on").expect("posts");
